// Extra controls that are not part of mocked products
type StoryControlsExtras = {
  descriptionText?: string;
  readMoreTextText?: string;
} & Pick<ProductInformationResponseItem, "stockLevel" | "ordinaryPrice">;

// Helper to convert empty strings to null for optional text fields
// Needed because Storybook text controls cannot be set to null directly
const nullifyEmpty = (val: string | null | undefined): string | null => {
  return typeof val === "string" && val.trim() === "" ? null : val ?? null;
};

// Normalize: allow simple strings for description/readMoreText and wrap plain text into <p>...</p>
// If the string looks like HTML, use it as-is
const toChildMarkdownRemark = (val: unknown) => {
  const nullCheckedVal = nullifyEmpty(val as string | null | undefined);
  if (typeof nullCheckedVal !== "string") return nullCheckedVal;
  const looksLikeHtml = /<\w|<\//.test(nullCheckedVal);
  const html = looksLikeHtml ? nullCheckedVal : `<p>${nullCheckedVal}</p>`;
  return { childMarkdownRemark: { html } };
};

// Story-level overrides are provided via context.loaded.productHookOverrides
const createMockProduct = (
  storyArgs: Partial<ProductBlockProps> & StoryControlsExtras = {},
): [ProductBlockFragment, ProductInformationResponseItem] => {
  const baseCFProduct: Partial<ProductBlockFragment> = {
    productData: { glkId: "12345", productType: "Standard" },
  };
  const baseGlkProduct: Partial<ProductInformationResponseItem> = {
    friendlySalesNameEng: storyArgs?.productName ?? undefined,
    friendlySalesNameSwe: storyArgs?.productName ?? undefined,
    id: 12345,
    priceIncludingVat: 199,
    isBuyable: true,
    ordinaryPrice: storyArgs?.ordinaryPrice ?? undefined,
    stockLevel: storyArgs?.stockLevel ?? undefined,
    minimumQuantity: 1,
    deliveryTypes: [{ deliveryType: DeliveryType.DIGITAL }],
  };

  const normalizedDescription = toChildMarkdownRemark(
    (storyArgs as StoryControlsExtras).descriptionText ?? (storyArgs as Partial<ProductBlockProps>).description,
  );
  const normalizedReadMoreText = toChildMarkdownRemark(
    (storyArgs as StoryControlsExtras).readMoreTextText ?? (storyArgs as Partial<ProductBlockProps>).readMoreText,
  );

  // Merge and nullify empty strings for optional text fields that are nullable in the component
  const mergedArgs = {
    ...storyArgs,
    description: normalizedDescription,
    readMoreText: normalizedReadMoreText,
    // Convert cleared text inputs back to null so the component behaves like "unset"
    readMoreLabel: nullifyEmpty(storyArgs.readMoreLabel),
    label: nullifyEmpty(storyArgs.label),
    backgroundColor: storyArgs.backgroundColor,
    customPriceText: nullifyEmpty(storyArgs.customPriceText),
    addedToCartHeadline: nullifyEmpty(storyArgs.addedToCartHeadline),
    addedToCartBody: nullifyEmpty(storyArgs.addedToCartBody),
    optionalLinkLabelText: nullifyEmpty(storyArgs.optionalLinkLabelText),
    optionalLinkUrl: nullifyEmpty(storyArgs.optionalLinkUrl),
  };

  return [
    { ...baseCFProduct, ...mergedArgs } as ProductBlockFragment,
    baseGlkProduct as ProductInformationResponseItem,
  ];
};

const meta: Meta<typeof ProductBlock> = {
  title: "Blocks/Product Block",
  component: ProductBlock,
  argTypes: {
    // Dropdown select with all existing themes
    ...argTypesComponentTheme,
    // Use string-based control fields that we map to markdown internally
    descriptionText: { control: { type: "text" }, name: "description" },
    readMoreTextText: { control: { type: "text" }, name: "readMoreText" },
    readMoreLabel: { control: { type: "text" } },
    label: { control: { type: "text" } },
    // Hide the object-shaped props to avoid confusing controls
    description: { table: { disable: true }, control: false },
    readMoreText: { table: { disable: true }, control: false },
    customPriceText: { control: { type: "text" } },
    backgroundColor: { control: { type: "boolean" } },
    optionalLinkLabelText: { control: { type: "text" } },
    optionalLinkUrl: { control: { type: "text" } },
    // Hide irrelevant fields from controls
    contentful_id: { table: { disable: true } },
    productData: { table: { disable: true } },
    setContextValues: { table: { disable: true } },
    preamble: { table: { disable: true } },
    addedToCartHeadline: { table: { disable: true } },
    addedToCartBody: { table: { disable: true } },
    // Expose selected product props as number controls
    price: { control: { type: "number" } },
    ordinaryPrice: { control: { type: "number" } },
    stockLevel: { control: { type: "number" } },
    minimumQuantity: { control: { type: "number" } },
    maximumQuantity: { control: { type: "number" } },
  } as unknown as Record<string, unknown>,
  args: {
    setContextValues: () => undefined,
    productData: {
      glkId: "12345",
      productType: "Standard",
    },
  },
  decorators: [
    (Story, context) => {
      // Root decorator to provide all necessary context providers
      // and handle args changes to update the mock store and query cache
      // without remounting the entire tree
      const DecoratorRoot = () => {
        const queryClientRef = useRef(new QueryClient());
        const queryClient = queryClientRef.current;

        const [cfProduct, glkProduct] = useMemo(
          () => createMockProduct({ ...context.args, ...context.loaded?.productHookOverrides }),
          [],
        );

        return (
          <PageProviders
            overrideQueryClient={queryClient}
            currentContentPageData={{
              currentLocale: "sv",
              slugs: { sv: "/", en: "/" },
            }}
            staticConfigData={{
              eCommerce: {} as any,
              products: {
                contentfulProducts: [cfProduct],
                glkProducts: [glkProduct],
              },
            }}
          >
            {(() => {
              type ArgsWithExtras = Partial<ProductBlockProps> & StoryControlsExtras;
              const a = context.args as ArgsWithExtras;
              const normalizedArgs = {
                ...a,
                description: toChildMarkdownRemark(a.descriptionText ?? a.description),
                readMoreText: toChildMarkdownRemark(a.readMoreTextText ?? a.readMoreText),
              } as Partial<ProductBlockProps>;
              return <Story args={normalizedArgs} />;
            })()}
          </PageProviders>
        );
      };

      return <DecoratorRoot />;
    },
  ],
  // Default loader sets a sane mock for all stories
  loaders: [
    async (_context) => {
      // Default: no overrides; story-specific loaders will set fields
      return { productHookOverrides: {} };
    },
  ],
};
export default meta;

